using Texts = std::vector<std::string>;

// ---- generated by scripts/make_r2_tests.py of the probe: the readers
[[nodiscard]] std::string readRadius(ApplicationSetterFixture& /*fixture*/,
                                     const RocketComponent& c)
{
    return listInOrder({asText(radiusMethodName(c.getRadiusMethod())), num(c.getRadiusOffset())});
}

[[nodiscard]] std::string readName(ApplicationSetterFixture& /*fixture*/, const RocketComponent& c)
{
    return c.getName();
}

