// The cases x150, x154 and x157 of the probe, through a setter of the test's own.
TEST(RadiusPositionSetter, SetsTheMethodAndThenTheOffset)
{
    const RadiusPositionSetter setter;
    EXPECT_EQ(applyByHand(setter, ComponentKind::POD_SET, "method=free", "0.1", &readRadius),
              "FREE, 0.1");
    // No method, and one the setter does not know: the surface, where the offset is 0.
    EXPECT_EQ(applyByHand(setter, ComponentKind::POD_SET, "", "0.2", &readRadius), "SURFACE, 0.0");
    EXPECT_EQ(applyByHand(setter, ComponentKind::POD_SET, "method=FREE", "0.12", &readRadius),
              "SURFACE, 0.0");
}

